"use client";

import { useState } from "react";
import styles from "./page.module.css";

type UserInfo = {
  name: string;
  age: number;
  phone: string;
};

type SignupInfo = {
  signupDate: string;
  signupIp: string;
  deviceOs: string;
};

const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_BASE_URL ?? "http://localhost:8091";

function formatPhoneNumber(phone: string): string {
  const digits = phone.replace(/\D/g, "");
  if (digits.length === 11) {
    return digits.replace(/(\d{3})(\d{4})(\d{4})/, "$1-$2-$3");
  }
  if (digits.length === 10) {
    return digits.replace(/(\d{3})(\d{3})(\d{4})/, "$1-$2-$3");
  }
  return phone;
}

async function fetchJson<T>(path: string): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${path}`);
  if (!res.ok) {
    throw new Error(`요청 실패 (status: ${res.status})`);
  }
  return res.json() as Promise<T>;
}

export default function Home() {
  const [userInfos, setUserInfos] = useState<UserInfo[] | null>(null);
  const [signupInfos, setSignupInfos] = useState<SignupInfo[] | null>(null);
  const [userLoading, setUserLoading] = useState(false);
  const [signupLoading, setSignupLoading] = useState(false);
  const [userError, setUserError] = useState<string | null>(null);
  const [signupError, setSignupError] = useState<string | null>(null);

  const handleFetchUserInfo = async () => {
    setUserLoading(true);
    setUserError(null);
    try {
      const data = await fetchJson<UserInfo[]>("/getuserinfo");
      setUserInfos(data);
    } catch {
      setUserError("사용자 정보를 불러오지 못했습니다. 백엔드 서버가 실행 중인지 확인해주세요.");
      setUserInfos(null);
    } finally {
      setUserLoading(false);
    }
  };

  const handleFetchSignupInfo = async () => {
    setSignupLoading(true);
    setSignupError(null);
    try {
      const data = await fetchJson<SignupInfo[]>("/getsignupinfo");
      setSignupInfos(data);
    } catch {
      setSignupError("가입일자 정보를 불러오지 못했습니다. 백엔드 서버가 실행 중인지 확인해주세요.");
      setSignupInfos(null);
    } finally {
      setSignupLoading(false);
    }
  };

  return (
    <div className={styles.page}>
      <main className={styles.main}>
        <div>
          <h1>사용자 정보 조회</h1>
          <p className={styles.description}>
            사용자 정보와 가입일자 정보를 서버 API를 통해 목록으로 조회합니다.
          </p>
        </div>

        <div className={styles.actions}>
          <button
            className={styles.button}
            onClick={handleFetchUserInfo}
            disabled={userLoading}
          >
            {userLoading ? "조회 중..." : "사용자 정보 조회"}
          </button>
          <button
            className={styles.button}
            onClick={handleFetchSignupInfo}
            disabled={signupLoading}
          >
            {signupLoading ? "조회 중..." : "가입일자 정보 조회"}
          </button>
        </div>

        <section className={styles.result}>
          <h2 className={styles.sectionTitle}>사용자 정보 조회 목록</h2>
          {userError && <p className={styles.error}>{userError}</p>}
          {userLoading && <p className={styles.placeholder}>사용자 정보를 조회 중입니다.</p>}

          {userInfos && userInfos.length > 0 && (
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>이름</th>
                  <th>나이</th>
                  <th>전화번호</th>
                </tr>
              </thead>
              <tbody>
                {userInfos.map((userInfo) => (
                  <tr key={`${userInfo.name}-${userInfo.phone}`}>
                    <td>{userInfo.name}</td>
                    <td>{userInfo.age}</td>
                    <td>{formatPhoneNumber(userInfo.phone)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {userInfos && userInfos.length === 0 && (
            <p className={styles.placeholder}>조회된 사용자 정보가 없습니다.</p>
          )}

          {!userInfos && !userError && !userLoading && (
            <p className={styles.placeholder}>
              사용자 정보 조회 버튼을 클릭하면 사용자 정보 목록이 표시됩니다.
            </p>
          )}
        </section>

        <section className={styles.result}>
          <h2 className={styles.sectionTitle}>가입일자 정보 조회 목록</h2>
          {signupError && <p className={styles.error}>{signupError}</p>}
          {signupLoading && <p className={styles.placeholder}>가입일자 정보를 조회 중입니다.</p>}

          {signupInfos && signupInfos.length > 0 && (
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>가입일자</th>
                  <th>가입 당시 사용자 IP</th>
                  <th>단말 OS</th>
                </tr>
              </thead>
              <tbody>
                {signupInfos.map((signupInfo) => (
                  <tr key={`${signupInfo.signupDate}-${signupInfo.signupIp}`}>
                    <td>{signupInfo.signupDate}</td>
                    <td>{signupInfo.signupIp}</td>
                    <td>{signupInfo.deviceOs}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {signupInfos && signupInfos.length === 0 && (
            <p className={styles.placeholder}>조회된 가입일자 정보가 없습니다.</p>
          )}

          {!signupInfos && !signupError && !signupLoading && (
            <p className={styles.placeholder}>
              가입일자 정보 조회 버튼을 클릭하면 가입일자 정보 목록이 표시됩니다.
            </p>
          )}
        </section>
      </main>
    </div>
  );
}

