package com.demo.back.getuserinfo;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.lang.reflect.Method;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.web.bind.annotation.GetMapping;

class GetUserInfoControllerTest {

    private final GetUserInfoController controller = new GetUserInfoController();

    @Test
    void getUserInfoIsMappedToGetuserinfoAndReturnsThreeUsers() throws Exception {
        Method method = GetUserInfoController.class.getMethod("getUserInfo");
        GetMapping mapping = method.getAnnotation(GetMapping.class);

        assertNotNull(mapping);
        assertArrayEquals(new String[]{"/getuserinfo"}, mapping.value());

        List<UserInfoResponse> users = controller.getUserInfo();

        assertEquals(3, users.size());
        assertEquals("james", invokeAccessor(users.get(0), "name"));
        assertEquals(26, invokeAccessor(users.get(0), "age"));
        assertEquals("01011112222", invokeAccessor(users.get(0), "phone"));
        assertEquals("sophia", invokeAccessor(users.get(1), "name"));
        assertEquals(31, invokeAccessor(users.get(1), "age"));
        assertEquals("01022223333", invokeAccessor(users.get(1), "phone"));
        assertEquals("minji", invokeAccessor(users.get(2), "name"));
        assertEquals(28, invokeAccessor(users.get(2), "age"));
        assertEquals("01033334444", invokeAccessor(users.get(2), "phone"));
