    void getSignupInfoIsMappedToGetsignupinfoAndReturnsThreeSignupRows() throws Exception {
        Method method = GetUserInfoController.class.getMethod("getSignupInfo");
        GetMapping mapping = method.getAnnotation(GetMapping.class);

        assertNotNull(mapping);
        assertArrayEquals(new String[]{"/getsignupinfo"}, mapping.value());

        List<SignupInfoResponse> signupInfos = controller.getSignupInfo();

        assertEquals(3, signupInfos.size());
        assertEquals("2024-01-15", signupInfos.get(0).signupDate());
