  });

  it("fetches /getuserinfo and renders user rows with formatted phone numbers", async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => [
        { name: "james", age: 26, phone: "01011112222" },
        { name: "sophia", age: 31, phone: "01022223333" },
      ],
    });

    render(<Home />);
    await userEvent.click(screen.getByRole("button", { name: "사용자 정보 조회" }));

    await waitFor(() =>
      expect(mockFetch).toHaveBeenCalledWith(expect.stringContaining("/getuserinfo"))
    );
    expect(await screen.findByText("james")).toBeInTheDocument();
    expect(screen.getByText("26")).toBeInTheDocument();
    expect(screen.getByText("010-1111-2222")).toBeInTheDocument();
    expect(screen.getByText("sophia")).toBeInTheDocument();
    expect(screen.getByText("010-2222-3333")).toBeInTheDocument();
  });

  it("fetches /getsignupinfo and renders signup rows", async () => {
    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => [
        { signupDate: "2024-01-15", signupIp: "203.0.113.10", deviceOs: "Windows 11" },
        { signupDate: "2024-02-03", signupIp: "203.0.113.21", deviceOs: "macOS 14" },
